import XCTest
@testable import Kria

/// The phone retimes per-clip label bars when clip timing changes, with the server's
/// `rebase_guided_text` rules. The vector file is generated BY the server function
/// (`tests/services/test_guided_label_rebase_vectors.py`); the same file is asserted here.
final class GuidedLabelRebaseVectorTests: XCTestCase {
    func testSourceBoundTextKeepsItsSourceAnchorWhenClipSpeedChanges() {
        let old = EditorTimelineSlot(id: "shot", clipIndex: 0, inS: 2, durationS: 6,
            raw: ["native_source_span_s": .number(6)])
        let next = EditorTimelineSlot(id: "shot", clipIndex: 0, inS: 2, durationS: 3,
            raw: ["native_source_span_s": .number(6), "playback_rate": .number(2)])
        let text = EditorTextElement(id: "free-text", text: "Anchor", startS: 1, endS: 2,
            raw: ["id": .string("free-text")])

        let rebased = try! XCTUnwrap(GuidedLabelRebase.rebase([text], oldSlots: [old], newSlots: [next], includeFreeText: true).first)
        XCTAssertEqual(rebased.startS, 0.5, accuracy: 0.000_001)
        XCTAssertEqual(rebased.endS, 1, accuracy: 0.000_001)
        let roundTrip = try! XCTUnwrap(GuidedLabelRebase.rebase([rebased], oldSlots: [next], newSlots: [old], includeFreeText: true).first)
        XCTAssertEqual(roundTrip.startS, 1, accuracy: 0.000_001)
        XCTAssertEqual(roundTrip.endS, 2, accuracy: 0.000_001)
    }

    func testSourceBoundTextUsesMarkedThirtyFPSWindowAfterHalfFrameSpeedRetime() {
        let old = (0..<2).map { index in
            EditorTimelineSlot(id: "speed-\(index)", clipIndex: index, inS: Double(index * 3), durationS: 3,
                raw: ["source_end_s": .number(Double(index * 3 + 3))])
        }
        let next = (0..<2).map { index in
            EditorTimelineSlot(id: "speed-\(index)", clipIndex: index, inS: Double(index * 3), durationS: 0.75,
                raw: ["source_end_s": .number(Double(index * 3 + 3)), "playback_rate": .number(4)])
        }
        let text = EditorTextElement(id: "free-text", text: "Anchor", startS: 3, endS: 3.5,
            raw: ["id": .string("free-text")])

        let rebased = try! XCTUnwrap(GuidedLabelRebase.rebase([text], oldSlots: old, newSlots: next, includeFreeText: true).first)
        XCTAssertEqual(rebased.startS, 22.0 / 30.0, accuracy: 0.000_001)
        XCTAssertEqual(rebased.endS, 28.0 / 30.0, accuracy: 0.000_001, "the minimum text-bar width extends the exact source projection")
        XCTAssertEqual(rebased.raw["segment_id"], .string("speed-1"))
    }

    private struct Vectors: Decodable {
        struct Case: Decodable {
            let name: String
            let oldSlots: [[String: JSONValue]]
            let newSlots: [[String: JSONValue]]
            let labelsBefore: [[String: JSONValue]]
            let labelsAfter: [[String: JSONValue]]
            enum CodingKeys: String, CodingKey {
                case name; case oldSlots = "old_slots"; case newSlots = "new_slots"
                case labelsBefore = "labels_before"; case labelsAfter = "labels_after"
            }
        }
        let toleranceS: Double
        let cases: [Case]
        enum CodingKeys: String, CodingKey { case toleranceS = "tolerance_s"; case cases }
    }

    private func vectors() throws -> Vectors {
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "guided_label_rebase_vectors", withExtension: "json"))
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    static func slot(_ row: [String: JSONValue]) -> EditorTimelineSlot {
        EditorTimelineSlot(
            id: row["slot_id"]?.stringValue,
            clipIndex: Int(row["clip_index"]?.numberValue ?? 0),
            inS: row["in_s"]?.numberValue ?? 0,
            durationS: row["duration_s"]?.numberValue,
            removed: row["removed"]?.boolValue ?? false,
            parentSegmentID: row["parent_segment_id"]?.stringValue,
            transitionAfter: row["transition_after"]?.stringValue ?? "cut",
            transitionDurationS: row["transition_duration_s"]?.numberValue,
            raw: row.filter { $0.key == "media_id" }
        )
    }

    private static func element(_ row: [String: JSONValue]) -> EditorTextElement {
        EditorTextElement(
            id: row["id"]?.stringValue ?? "", text: row["text"]?.stringValue ?? "",
            startS: row["start_s"]?.numberValue ?? 0, endS: row["end_s"]?.numberValue ?? 0,
            role: row["role"]?.stringValue, raw: row
        )
    }

    func testEveryServerGeneratedVectorMatches() throws {
        let file = try vectors()
        XCTAssertGreaterThanOrEqual(file.cases.count, 10)
        for vector in file.cases {
            let before = vector.labelsBefore.map(Self.element)
            let after = GuidedLabelRebase.rebase(
                before, oldSlots: vector.oldSlots.map(Self.slot), newSlots: vector.newSlots.map(Self.slot), includeFreeText: true
            )
            XCTAssertEqual(after.map(\.id), vector.labelsAfter.compactMap { $0["id"]?.stringValue }, vector.name)
            for (actual, expected) in zip(after, vector.labelsAfter) {
                XCTAssertEqual(actual.startS, expected["start_s"]?.numberValue ?? .nan, accuracy: file.toleranceS, "\(vector.name) \(actual.id) start")
                XCTAssertEqual(actual.endS, expected["end_s"]?.numberValue ?? .nan, accuracy: file.toleranceS, "\(vector.name) \(actual.id) end")
                XCTAssertEqual(actual.raw["segment_id"]?.stringValue, expected["segment_id"]?.stringValue, "\(vector.name) \(actual.id) segment")
            }
        }
    }

    func testRebaseNeverChangesTextStyleOrPositionAndLeavesNonLabelBarsExact() throws {
        let file = try vectors()
        let vector = try XCTUnwrap(file.cases.first { $0.name == "extend_clip1_by_0_533" })
        let before = vector.labelsBefore.map(Self.element)
        let after = GuidedLabelRebase.rebase(before, oldSlots: vector.oldSlots.map(Self.slot), newSlots: vector.newSlots.map(Self.slot), includeFreeText: true)
        let volatile: Set<String> = ["start_s", "end_s", "segment_id"]
        for (old, new) in zip(before, after) {
            XCTAssertEqual(old.text, new.text)
            XCTAssertEqual(old.raw.filter { !volatile.contains($0.key) }, new.raw.filter { !volatile.contains($0.key) }, old.id)
            if !GuidedLabelRebase.isClipLabel(old) { XCTAssertEqual(old, new, "\(old.id) must be untouched") }
        }
        XCTAssertEqual(after.filter(GuidedLabelRebase.isClipLabel).count, 5)
    }

    func testLabelWithNoIdentifiableSlotIsProjectedAsOrdinaryTextOnAGuidedStory() throws {
        let file = try vectors()
        let vector = try XCTUnwrap(file.cases.first { $0.name == "extend_clip1_by_0_533" })
        let orphan = EditorTextElement(id: "clip-label-unified-cut-9", text: "Mystery", startS: 5, endS: 6, raw: ["id": .string("clip-label-unified-cut-9")])
        let after = GuidedLabelRebase.rebase([orphan], oldSlots: vector.oldSlots.map(Self.slot), newSlots: vector.newSlots.map(Self.slot), includeFreeText: true)
        XCTAssertEqual(after.first?.startS ?? -1, 5.533, accuracy: 0.002, "follows the footage it sat over instead of staying put")
        XCTAssertEqual(after.first?.endS ?? -1, 6.533, accuracy: 0.002)
        let notGuided = GuidedLabelRebase.rebase([orphan], oldSlots: vector.oldSlots.map(Self.slot), newSlots: vector.newSlots.map(Self.slot), includeFreeText: false)
        XCTAssertEqual(notGuided, [orphan], "outside a guided story an unidentifiable bar is left alone")
    }

    func testMontageTextIsLeftAloneOutsideAGuidedStory() throws {
        let file = try vectors()
        let vector = try XCTUnwrap(file.cases.first { $0.name == "extend_clip1_by_0_533" })
        let bar = EditorTextElement(id: "montage-text-cut-2", text: "Shot", startS: 2, endS: 4, raw: ["id": .string("montage-text-cut-2"), "segment_id": .string("s2")])
        XCTAssertFalse(GuidedLabelRebase.hasLabels([bar], includeFreeText: false))
        XCTAssertEqual(GuidedLabelRebase.rebase([bar], oldSlots: vector.oldSlots.map(Self.slot), newSlots: vector.newSlots.map(Self.slot), includeFreeText: false), [bar])
    }

    func testTextOverlappingNoClipIsLeftWhereItIsNotDropped() throws {
        let file = try vectors()
        let vector = try XCTUnwrap(file.cases.first { $0.name == "extend_clip1_by_0_533" })
        let stale = EditorTextElement(id: "kria-text-stale", text: "Past the end", startS: 40, endS: 42, raw: ["id": .string("kria-text-stale")])
        let after = GuidedLabelRebase.rebase([stale], oldSlots: vector.oldSlots.map(Self.slot), newSlots: vector.newSlots.map(Self.slot), includeFreeText: true)
        XCTAssertEqual(after, [stale])
    }

    /// The editor's guided timeline slots name their source by clip_index only, so a
    /// `clip-label-media-<id>` bar without a segment_id must resolve through the source pool.
    func testMediaLinkedLabelResolvesThroughSourcePoolWhenSlotsCarryNoMediaID() throws {
        let file = try vectors()
        let vector = try XCTUnwrap(file.cases.first { $0.name == "media_link_without_segment_id_follows_by_overlap" })
        func bare(_ row: [String: JSONValue]) -> EditorTimelineSlot {
            var slot = Self.slot(row); slot.raw = [:]; return slot
        }
        let media = Dictionary(uniqueKeysWithValues: (0..<5).map { ($0, "m\($0)") })
        let before = vector.labelsBefore.map(Self.element)
        let withPool = GuidedLabelRebase.rebase(before, oldSlots: vector.oldSlots.map(bare), newSlots: vector.newSlots.map(bare), mediaByClipIndex: media, includeFreeText: true)
        let withoutPool = GuidedLabelRebase.rebase(before, oldSlots: vector.oldSlots.map(bare), newSlots: vector.newSlots.map(bare), includeFreeText: true)
        for (actual, expected) in zip(withPool, vector.labelsAfter) {
            XCTAssertEqual(actual.startS, expected["start_s"]?.numberValue ?? .nan, accuracy: file.toleranceS, actual.id)
            XCTAssertEqual(actual.endS, expected["end_s"]?.numberValue ?? .nan, accuracy: file.toleranceS, actual.id)
        }
        XCTAssertLessThan(withoutPool.filter { $0.id.hasPrefix("clip-label-media-m") }.count, 5, "documents why the pool is needed: labels were dropped without it")
    }

    func testEmptyNewTimelineNeverWipesTheLabels() throws {
        let vector = try XCTUnwrap(vectors().cases.first)
        let before = vector.labelsBefore.map(Self.element)
        XCTAssertEqual(GuidedLabelRebase.rebase(before, oldSlots: vector.oldSlots.map(Self.slot), newSlots: [], includeFreeText: true), before)
    }
}

/// Handler-level: every clip-timing edit in the native editor carries the labels with it.
@MainActor
final class GuidedLabelRippleSessionTests: XCTestCase {
    private static let jobID = "5b1d2f0a-6c0e-4b8e-9d0a-1c2d3e4f5a6b"

    private static func slot(_ id: String, _ index: Double, transition: String = "cut") -> JSONValue {
        .object(["slot_id": .string(id), "clip_index": .number(index), "in_s": .number(0), "duration_s": .number(2),
                 "source_duration_s": .number(10), "removed": .bool(false), "transition_after": .string(transition)])
    }

    private static func label(_ n: Int, _ start: Double, _ end: Double) -> JSONValue {
        .object(["id": .string("clip-label-unified-cut-\(n)"), "text": .string("Place \(n)"), "start_s": .number(start), "end_s": .number(end),
                 "segment_id": .string("s\(n)"), "role": .string("generative_intro"), "font_family": .string("DM Sans"),
                 "size_px": .number(58), "x_frac": .number(0.5), "y_frac": .number(0.78), "color": .string("#FFF8F0")])
    }

    private static func free(_ id: String, _ start: Double, _ end: Double, text: String = "Free") -> JSONValue {
        .object(["id": .string(id), "text": .string(text), "start_s": .number(start), "end_s": .number(end),
                 "role": .string("generative_intro"), "position": .string("custom"), "x_frac": .number(0.5), "y_frac": .number(0.4)])
    }

    private static func variant(includeLabels: Bool = true, extraText: [JSONValue] = [], archetype: String = "guided_story") -> [String: JSONValue] {
        var textElements: [JSONValue] = [
            .object(["id": .string("guided-title"), "text": .string("Weekend"), "start_s": .number(0), "end_s": .number(8), "role": .string("generative_intro")]),
            .object(["id": .string("guided-closing-title"), "text": .string("See you"), "start_s": .number(6), "end_s": .number(8), "role": .string("generative_outro")]),
        ]
        if includeLabels {
            textElements += [label(1, 0, 2), label(2, 2, 4), label(3, 4, 6), label(4, 6, 8)]
        }
        textElements += extraText
        textElements.append(.object(["id": .string("caption-1"), "text": .string("spoken"), "start_s": .number(2.5), "end_s": .number(3.5),
                                     "source_params": .object(["source": .string("caption_cue")])]))
        let userTimelineSlots = (1...4).map { slot("s\($0)", Double($0 - 1)) }
        return [
            "variant_id": .string("initial"), "render_generation_id": .string("g1"), "render_status": .string("ready"),
            "duration_s": .number(8), "output_url": .string("file:///tmp/kria-label-ripple.mp4"),
            "resolved_archetype": .string(archetype), "base_video_path": .string("base.mp4"),
            "editor_capabilities": .object(["timeline": .bool(true), "text_elements": .bool(true), "mix": .bool(true)]),
            "user_timeline": .object(["slots": .array(userTimelineSlots)]),
            "text_elements": .array(textElements),
        ]
    }

    private func loaded(includeLabels: Bool = true, extraText: [JSONValue] = [], archetype: String = "guided_story") async -> (NativeEditorSession, EditorCommitSpy) {
        let bootstrap = DraftSnapshot(draftID: "d1", itemID: "item", variantKey: "initial", draftRevision: 1, snapshotHash: "h", etag: "e",
            baseJobID: Self.jobID, baseGenerationID: "g1",
            snapshot: ["kind": .string("editor"), "editor_payload": .object(["base_generation": .string("g1"), "sections": .object([:])])],
            canUndo: false, createdAt: .now)
        let fake = EditorCommitSpy(draftSnapshot: bootstrap, authoritativeVariant: Self.variant(includeLabels: includeLabels, extraText: extraText, archetype: archetype),
            commitResponse: EditorCommitResponse(ok: true, generation: "g2",
                sections: EditorCommitSections(textElements: true, captionMeta: false, timeline: true, mix: false),
                revisionNumber: 4, revisionHash: "r4", expectedDuration: nil))
        let session = NativeEditorSession()
        await session.load(api: fake, threadID: UUID())
        return (session, fake)
    }

    private func label(_ session: NativeEditorSession, _ n: Int) -> EditorTextElement? {
        session.document.textElements.first { $0.id == "clip-label-unified-cut-\(n)" }
    }

    func testExtendingClip1ShiftsEveryLaterLabelAndOneUndoRestoresBoth() async throws {
        let (session, _) = await loaded()
        XCTAssertEqual(label(session, 1)?.endS, 2)
        let originalText = session.document.textElements
        let originalClips = session.document.clips
        session.setClipTiming(clipID: "s1", durationS: 2.533)
        XCTAssertEqual(label(session, 1)?.startS ?? -1, 0, accuracy: 0.001)
        XCTAssertEqual(label(session, 1)?.endS ?? -1, 2.533, accuracy: 0.001)
        for n in 2...4 {
            XCTAssertEqual(label(session, n)?.startS ?? -1, 2.533 + Double(n - 2) * 2, accuracy: 0.001, "label \(n)")
            XCTAssertEqual(label(session, n)?.endS ?? -1, 2.533 + Double(n - 1) * 2, accuracy: 0.001, "label \(n)")
        }
        XCTAssertTrue(session.dirtySections.contains(.text), "retimed labels must be saved, not just timeline_slots")
        XCTAssertTrue(session.dirtySections.contains(.timeline))
        session.undo()
        XCTAssertEqual(session.document.textElements, originalText)
        XCTAssertEqual(session.document.clips, originalClips)
        XCTAssertFalse(session.canUndo, "a single Undo reverted the clip AND its labels")
        XCTAssertTrue(session.dirtySections.isEmpty)
        session.redo()
        XCTAssertEqual(label(session, 4)?.endS ?? -1, 8.533, accuracy: 0.001)
    }

    func testTitleOnlyGuidedSessionRebasesAndOneUndoRestoresBoth() async throws {
        let (session, _) = await loaded(includeLabels: false)
        let originalText = session.document.textElements
        let originalClips = session.document.clips
        XCTAssertFalse(session.document.textElements.contains(where: GuidedLabelRebase.isClipLabel))
        XCTAssertTrue(GuidedLabelRebase.hasLabels(session.document.textElements, includeFreeText: true), "title-only guided stories still use the rebase transaction")

        session.setClipTiming(clipID: "s1", durationS: 2.533)
        let title = try XCTUnwrap(session.document.textElements.first { $0.id == "guided-title" })
        let closing = try XCTUnwrap(session.document.textElements.first { $0.id == "guided-closing-title" })
        XCTAssertEqual(title.startS, 0, accuracy: 0.001)
        XCTAssertEqual(title.endS, 8.533, accuracy: 0.001)
        XCTAssertEqual(closing.startS, 6.533, accuracy: 0.001)
        XCTAssertEqual(closing.endS, 8.533, accuracy: 0.001)
        XCTAssertTrue(session.dirtySections.contains(.text))

        session.undo()
        XCTAssertEqual(session.document.textElements, originalText)
        XCTAssertEqual(session.document.clips, originalClips)
        XCTAssertFalse(session.canUndo)
    }

    func testTrimGestureRipplesLabelsFromTheBaselineWithOneUndoStep() async throws {
        let (session, _) = await loaded()
        let original = session.document.textElements
        let clip = try XCTUnwrap(session.timelineClips.first)
        session.beginTrim(clipID: clip.id, edge: .trailing)
        for translation in [0.2, 0.4, 0.533] { session.updateTrim(by: translation) }
        session.endTrim()
        XCTAssertEqual(label(session, 1)?.endS ?? -1, 2.533, accuracy: 0.001)
        XCTAssertEqual(label(session, 3)?.startS ?? -1, 4.533, accuracy: 0.001, "no cumulative drift across gesture updates")
        session.undo()
        XCTAssertEqual(session.document.textElements, original)
        XCTAssertFalse(session.canUndo)
    }

    func testTrimSelectedFollowsToo() async throws {
        let (session, _) = await loaded()
        let clip = try XCTUnwrap(session.timelineClips.first)
        session.selectClip(clip.id)
        session.trimSelected(edge: .trailing, to: clip.end + 0.533)
        XCTAssertEqual(label(session, 2)?.startS ?? -1, 2.533, accuracy: 0.001)
    }

    func testShorteningKeepsAHandDelayedStartScaled() async throws {
        let (session, _) = await loaded()
        // Creator delayed label 1's start by 0.6s (window 0-2, bar 0.6-1.8).
        var delayed = try XCTUnwrap(label(session, 1))
        delayed.startS = 0.6; delayed.endS = 1.8
        session.transactDocument(section: .text) { doc in
            if let index = doc.textElements.firstIndex(where: { $0.id == delayed.id }) { doc.textElements[index] = delayed }
        }
        session.setClipTiming(clipID: "s1", durationS: 1.0)
        XCTAssertEqual(label(session, 1)?.startS ?? -1, 0.3, accuracy: 0.001)
        XCTAssertEqual(label(session, 1)?.endS ?? -1, 0.9, accuracy: 0.001)
    }

    func testReorderDeleteAndTransitionAllMoveLabels() async throws {
        let (session, _) = await loaded()
        let clip2 = try XCTUnwrap(session.timelineClips.dropFirst().first)
        session.selectClip(clip2.id)
        session.moveSelected(by: 1)
        XCTAssertEqual(label(session, 3)?.startS ?? -1, 2, accuracy: 0.001, "reorder: clip 3 now plays second")
        XCTAssertEqual(label(session, 2)?.startS ?? -1, 4, accuracy: 0.001)

        session.removeClip(clipID: "s1")
        XCTAssertNil(label(session, 1), "a deleted clip's label goes with it")
        XCTAssertEqual(label(session, 3)?.startS ?? -1, 0, accuracy: 0.001)
        XCTAssertEqual(label(session, 4)?.startS ?? -1, 4, accuracy: 0.001)

        session.undo()
        XCTAssertNotNil(label(session, 1), "undo brings the deleted clip's label back")
        XCTAssertEqual(label(session, 3)?.startS ?? -1, 2, accuracy: 0.001)

        session.setClipTransition(clipID: "s1", transition: "crossfade", durationS: 0.3)
        XCTAssertEqual(label(session, 3)?.startS ?? -1, 1.7, accuracy: 0.001, "transition overlap pulls later windows earlier")
    }

    func testDeleteSelectedClipDropsItsLabelAndRipplesTheRest() async throws {
        let (session, _) = await loaded()
        let clip2 = try XCTUnwrap(session.timelineClips.dropFirst().first)
        session.selectClip(clip2.id)
        session.deleteSelectedClip()
        XCTAssertNil(label(session, 2))
        XCTAssertEqual(label(session, 3)?.startS ?? -1, 2, accuracy: 0.001)
        XCTAssertEqual(label(session, 4)?.endS ?? -1, 6, accuracy: 0.001)
        XCTAssertEqual(label(session, 1)?.segmentIDForTest, "s1")
    }

    func testHandEditedTextStyleAndNonLabelBarsSurvive() async throws {
        let (session, _) = await loaded()
        session.setTextStyle(id: "clip-label-unified-cut-2", style: "Inter")
        let styled = try XCTUnwrap(label(session, 2))
        let title = session.document.textElements.first { $0.id == "guided-title" }
        let caption = session.document.textElements.first { $0.id == "caption-1" }
        session.setClipTiming(clipID: "s1", durationS: 2.533)
        let after = try XCTUnwrap(label(session, 2))
        XCTAssertEqual(after.text, styled.text)
        let volatile: Set<String> = ["start_s", "end_s", "segment_id"]
        XCTAssertEqual(after.raw.filter { !volatile.contains($0.key) }, styled.raw.filter { !volatile.contains($0.key) })
        let rebasedTitle = try XCTUnwrap(session.document.textElements.first { $0.id == "guided-title" })
        XCTAssertEqual(rebasedTitle.text, title?.text)
        XCTAssertEqual(rebasedTitle.raw.filter { !volatile.contains($0.key) }, title?.raw.filter { !volatile.contains($0.key) })
        XCTAssertEqual(rebasedTitle.startS, 0, accuracy: 0.001)
        XCTAssertEqual(rebasedTitle.endS, 8.533, accuracy: 0.001)
        XCTAssertEqual(session.document.textElements.first { $0.id == "caption-1" }, caption)
    }

    /// KRI-715: a montage with a group title, a chat-added text and per-shot copy, none of them a
    /// `clip-label-*`. Every clip edit used to leave all of this at its old seconds.
    private static let montageText: [JSONValue] = [
        free("group-title-0", 0, 6, text: "Group title"),
        free("kria-chat-1", 3, 5, text: "Chat text"),
        .object(["id": .string("montage-text-cut-2"), "text": .string("Shot 2"), "start_s": .number(2), "end_s": .number(4),
                 "segment_id": .string("s2"), "role": .string("generative_intro"), "position": .string("custom")]),
        free("kria-late", 6.5, 7.5, text: "Late"),
    ]

    private func text(_ session: NativeEditorSession, _ id: String) -> EditorTextElement? {
        session.document.textElements.first { $0.id == id }
    }

    func testDeletingAMiddleClipKeepsEveryTextAndMovesIt() async throws {
        let (session, _) = await loaded(includeLabels: false, extraText: Self.montageText)
        let original = session.document.textElements
        session.removeClip(clipID: "s2")
        let group = try XCTUnwrap(text(session, "group-title-0"))
        XCTAssertEqual(group.startS, 0, accuracy: 0.04)
        XCTAssertEqual(group.endS, 4, accuracy: 0.04, "the group title shrinks with the group, still one block")
        let chat = try XCTUnwrap(text(session, "kria-chat-1"), "a text starting in the deleted clip survives while any clip under it does")
        XCTAssertEqual(chat.startS, 2, accuracy: 0.04)
        XCTAssertEqual(chat.endS, 3, accuracy: 0.04)
        XCTAssertNil(text(session, "montage-text-cut-2"), "per-shot copy goes with its own clip")
        let late = try XCTUnwrap(text(session, "kria-late"))
        XCTAssertEqual(late.startS, 4.5, accuracy: 0.04)
        XCTAssertEqual(late.endS, 5.5, accuracy: 0.04)
        XCTAssertTrue(session.dirtySections.contains(.text))
        session.undo()
        XCTAssertEqual(session.document.textElements, original, "one Undo restores the clip and all of its text")
        XCTAssertFalse(session.canUndo)
    }

    func testShorteningAndExtendingAClipMoveFreeTextWithTheFootage() async throws {
        let (session, _) = await loaded(includeLabels: false, extraText: Self.montageText)
        session.setClipTiming(clipID: "s1", durationS: 1.0)
        XCTAssertEqual(text(session, "kria-late")?.startS ?? -1, 5.5, accuracy: 0.04)
        XCTAssertEqual(text(session, "kria-late")?.endS ?? -1, 6.5, accuracy: 0.04)
        XCTAssertEqual(text(session, "group-title-0")?.endS ?? -1, 5, accuracy: 0.04)
        XCTAssertEqual(text(session, "kria-chat-1")?.startS ?? -1, 2, accuracy: 0.04)
        session.setClipTiming(clipID: "s1", durationS: 2.533)
        XCTAssertEqual(text(session, "kria-late")?.startS ?? -1, 7.033, accuracy: 0.04)
        XCTAssertEqual(text(session, "montage-text-cut-2")?.startS ?? -1, 2.533, accuracy: 0.04)
        XCTAssertEqual(text(session, "group-title-0")?.endS ?? -1, 6.533, accuracy: 0.04)
    }

    func testTextPastTheNewEndAfterAShortenStaysVisibleAtTheTail() async throws {
        let (session, _) = await loaded(includeLabels: false, extraText: [Self.free("kria-tail", 7.2, 8, text: "Tail")])
        session.setClipTiming(clipID: "s4", durationS: 1.0)
        let tail = try XCTUnwrap(text(session, "kria-tail"))
        XCTAssertLessThanOrEqual(tail.endS, 7.0 + 0.001)
        XCTAssertGreaterThan(tail.endS - tail.startS, 0.1)
        XCTAssertGreaterThanOrEqual(tail.startS, 0)
    }

    func testSaveSendsRetimedFreeTextWithTheTimeline() async throws {
        let (session, fake) = await loaded(includeLabels: false, extraText: Self.montageText)
        session.removeClip(clipID: "s2")
        await session.save()
        let request = try XCTUnwrap(fake.lastRequest)
        let rows = try XCTUnwrap(request.textElements).compactMap(\.objectValue)
        let late = try XCTUnwrap(rows.first { $0["id"]?.stringValue == "kria-late" })
        XCTAssertEqual(late["start_s"]?.numberValue ?? -1, 4.5, accuracy: 0.04, "the server skips projecting authored text, so the phone must send it re-timed")
        XCTAssertNil(rows.first { $0["id"]?.stringValue == "montage-text-cut-2" })
    }

    /// Speech-timed archetypes keep their own text rules (the speech compiler re-times them).
    func testFreeTextIsLeftAloneOnSpeechTimedArchetypes() async throws {
        for archetype in ["subtitled", "narrated", "talking_head"] {
            let (session, _) = await loaded(includeLabels: false, extraText: Self.montageText, archetype: archetype)
            session.removeClip(clipID: "s2")
            XCTAssertEqual(text(session, "kria-late")?.startS, 6.5, archetype)
            XCTAssertEqual(text(session, "kria-chat-1")?.startS, 3, archetype)
        }
    }

    /// KRI-715 follow-up: a montage-family edit (no `resolved_archetype`, "montage", voiceover ...)
    /// is a clip timeline too; its text must follow a delete exactly like a guided story's.
    func testFreeTextFollowsADeleteOnMontageFamilyArchetypes() async throws {
        for archetype in ["montage", "voiceover", "day_vlog", "single_hero"] {
            let (session, _) = await loaded(includeLabels: false, extraText: Self.montageText, archetype: archetype)
            session.removeClip(clipID: "s2")
            XCTAssertEqual(text(session, "kria-late")?.startS ?? -1, 4.5, accuracy: 0.04, archetype)
            XCTAssertEqual(text(session, "kria-chat-1")?.startS ?? -1, 2, accuracy: 0.04, archetype)
            XCTAssertNil(text(session, "montage-text-cut-2"), archetype)
        }
    }

    func testEditsThatMoveNoWindowLeaveTextClean() async throws {
        let (session, _) = await loaded()
        session.setClipLookPreset(clipID: "s1", preset: "golden_hour")
        XCTAssertEqual(session.dirtySections, [.timeline])
    }

    func testSavePayloadCarriesRebasedTextElementsWithTimelineSlots() async throws {
        let (session, fake) = await loaded()
        session.setClipTiming(clipID: "s1", durationS: 2.533)
        await session.save()
        let request = try XCTUnwrap(fake.lastRequest)
        XCTAssertNotNil(request.timelineSlots)
        let rows = try XCTUnwrap(request.textElements)
        let second = try XCTUnwrap(rows.compactMap(\.objectValue).first { $0["id"]?.stringValue == "clip-label-unified-cut-2" })
        XCTAssertEqual(second["start_s"]?.numberValue ?? -1, 2.533, accuracy: 0.001)
        XCTAssertEqual(second["segment_id"]?.stringValue, "s2")
    }

    func testTimelineOnlyCommitOnAGuidedStoryStillSendsText() async throws {
        let (session, fake) = await loaded()
        session.setClipLookPreset(clipID: "s1", preset: "golden_hour")
        await session.save()
        let request = try XCTUnwrap(fake.lastRequest)
        XCTAssertNotNil(request.timelineSlots)
        XCTAssertNotNil(request.textElements, "server treats text as authored and skips its label-unaware projection")
    }
}


/// KRI-715 follow-up: the same delete, on documents shaped like REAL phone-montage payloads
/// (prod job fixtures: slot_id == segment id, no media_id on slots, `user_timeline.clips` carrying
/// media ids, per-cut labels with no segment_id, `clip-label-media-<id>` bars, `kria-<hex>` chat
/// text, `group-title-montage-N`, `montage-text-<cut>`), across every archetype value a phone
/// editor can open a timeline for.
@MainActor
final class GuidedTextFollowsDeleteRealShapeTests: XCTestCase {
    private static let jobID = "5b1d2f0a-6c0e-4b8e-9d0a-1c2d3e4f5a6c"
    private static let clipCount = 8
    private static let clipS = 1.0

    private static func segment(_ n: Int) -> String { "seg-\(n)" }
    private static func media(_ n: Int) -> String { "analysis-proxy-ios-M\(n).mp4" }

    private static func slot(_ n: Int) -> JSONValue {
        .object(["slot_id": .string(segment(n)), "segment_id": .string(segment(n)), "parent_segment_id": .null,
                 "clip_index": .number(Double(n)), "in_s": .number(0), "duration_s": .number(clipS),
                 "source_duration_s": .number(5), "output_start_s": .number(Double(n) * clipS),
                 "output_end_s": .number(Double(n + 1) * clipS), "removed": .bool(false),
                 "transition_after": .string("cut"), "transition_duration_s": .null, "look_preset": .string("none")])
    }

    private static func bar(_ id: String, _ start: Double, _ end: Double, text: String, segment: String? = nil) -> JSONValue {
        var row: [String: JSONValue] = ["id": .string(id), "text": .string(text), "start_s": .number(start), "end_s": .number(end),
                                         "role": .string("generative_intro"), "position": .string("custom"),
                                         "x_frac": .number(0.5), "y_frac": .number(0.78)]
        if let segment { row["segment_id"] = .string(segment) }
        return .object(row)
    }

    static func variant(archetype: String?, device: Bool = true) -> [String: JSONValue] {
        let total = Double(clipCount) * clipS
        let text: [JSONValue] = [
            bar("guided-title", 0, 2, text: "Title"),
            bar("clip-label-unified-cut-5", 4, 5, text: "Cut five"),
            bar("clip-label-media-\(media(6))", 5, 6, text: "Media six"),
            bar("montage-text-unified-cut-3", 2, 3, text: "Shot three"),
            bar("group-title-montage-1", 4, 8, text: "Group"),
            bar("kria-0f3a9c", 3.5, 6.5, text: "Chat text"),
            bar("kria-tail", 7, 8, text: "Tail"),
            bar("guided-pinned-0", 0, total, text: "Pinned"),
        ]
        var variant: [String: JSONValue] = [
            "variant_id": .string("initial"), "render_generation_id": .string("g1"), "render_status": .string("ready"),
            "duration_s": .number(total), "output_url": .string("file:///tmp/kria-real-shape.mp4"),
            "render_destination": .string(device ? "device" : "cloud"),
            "editor_capabilities": .object(["timeline": .bool(true), "text_elements": .bool(true), "mix": .bool(true)]),
            "user_timeline": .object([
                "slots": .array((0..<clipCount).map(slot)),
                "clips": .array((0..<clipCount).map { .object(["clip_index": .number(Double($0)), "media_id": .string(media($0))]) }),
            ]),
            "text_elements": .array(text),
        ]
        if let archetype { variant["resolved_archetype"] = .string(archetype) }
        return variant
    }

    private func loaded(archetype: String?, device: Bool = true) async -> NativeEditorSession {
        let bootstrap = DraftSnapshot(draftID: "d1", itemID: "item", variantKey: "initial", draftRevision: 1, snapshotHash: "h", etag: "e",
            baseJobID: Self.jobID, baseGenerationID: "g1",
            snapshot: ["kind": .string("editor"), "editor_payload": .object(["base_generation": .string("g1"), "sections": .object([:])])],
            canUndo: false, createdAt: .now)
        let fake = EditorCommitSpy(draftSnapshot: bootstrap, authoritativeVariant: Self.variant(archetype: archetype, device: device),
            commitResponse: EditorCommitResponse(ok: true, generation: "g2",
                sections: EditorCommitSections(textElements: true, captionMeta: false, timeline: true, mix: false),
                revisionNumber: 4, revisionHash: "r4", expectedDuration: nil))
        let session = NativeEditorSession()
        await session.load(api: fake, threadID: UUID())
        return session
    }

    private func assertDeleteKeepsText(archetype: String?, file: StaticString = #filePath, line: UInt = #line) async throws {
        let session = await loaded(archetype: archetype)
        func text(_ id: String) -> EditorTextElement? { session.document.textElements.first { $0.id == id } }
        XCTAssertNotNil(text("kria-tail"), "fixture loaded", file: file, line: line)
        session.removeClip(clipID: Self.segment(2))
        XCTAssertEqual(session.document.clips.count, Self.clipCount - 1, "clip deleted", file: file, line: line)
        // Every text whose own clip survives is still there, and nothing starts at/after the new 7s total.
        for id in ["guided-title", "clip-label-unified-cut-5", "clip-label-media-\(Self.media(6))", "group-title-montage-1",
                   "kria-0f3a9c", "kria-tail", "guided-pinned-0"] {
            let bar = text(id)
            XCTAssertNotNil(bar, "\(id) must survive deleting a clip it does not sit on (\(archetype ?? "nil"))", file: file, line: line)
            if let bar { XCTAssertLessThan(bar.startS, 7, "\(id) must start inside the new 7s video", file: file, line: line) }
        }
        XCTAssertEqual(text("kria-tail")?.startS ?? -1, 6, accuracy: 0.04, "later text ripples left with its footage", file: file, line: line)
        XCTAssertEqual(text("kria-tail")?.endS ?? -1, 7, accuracy: 0.04, file: file, line: line)
        XCTAssertEqual(text("clip-label-unified-cut-5")?.startS ?? -1, 3, accuracy: 0.04, file: file, line: line)
        XCTAssertNil(text("montage-text-unified-cut-3"), "per-shot copy goes with its own clip", file: file, line: line)
        XCTAssertEqual(text("guided-pinned-0")?.endS ?? -1, 7, accuracy: 0.04, file: file, line: line)
    }

    func testSpeechTimedArchetypeKeepsItsOwnTextRules() async throws {
        let session = await loaded(archetype: "subtitled")
        session.removeClip(clipID: Self.segment(2))
        XCTAssertEqual(session.document.textElements.first { $0.id == "kria-tail" }?.startS, 7)
    }

    func testCloudMontageWithoutArchetype() async throws {
        let session = await loaded(archetype: nil, device: false)
        session.removeClip(clipID: Self.segment(2))
        XCTAssertEqual(session.document.textElements.first { $0.id == "kria-tail" }?.startS ?? -1, 6, accuracy: 0.04)
    }

    func testGuidedStory() async throws { try await assertDeleteKeepsText(archetype: "guided_story") }
    func testMontageWithNoArchetypeKey() async throws { try await assertDeleteKeepsText(archetype: nil) }
    func testMontage() async throws { try await assertDeleteKeepsText(archetype: "montage") }
    func testVoiceoverMontage() async throws { try await assertDeleteKeepsText(archetype: "voiceover") }
    func testDayVlog() async throws { try await assertDeleteKeepsText(archetype: "day_vlog") }
    func testSingleHero() async throws { try await assertDeleteKeepsText(archetype: "single_hero") }
}

private extension EditorTextElement { var segmentIDForTest: String? { raw["segment_id"]?.stringValue } }
